def flipLights(n, presses):
    if presses == 0:
        return 1

    # The key insight: the state of the lights can be represented by a bitmask or tuple,
    # but we can also notice that there are only a limited number of distinct states
    # reachable with at most `presses` button presses.

    # We'll use BFS (breadth-first search) to explore all possible states.
    from collections import deque

    # Initial state: all bulbs are on
    initial_state = tuple([1] * n)
    queue = deque([initial_state])
    visited = set([initial_state])

    # Define the four button operations as functions that take a state and return the new state
    def button1(state):
        return tuple(1 - state[i] for i in range(n))

    def button2(state):
        return tuple(state[i] if i % 2 == 1 else 1 - state[i] for i in range(n))

    def button3(state):
        return tuple(state[i] if i % 2 == 0 else 1 - state[i] for i in range(n))

    def button4(state):
        new_state = list(state)
        for i in range(n):
            if (i + 1) % 3 == 1:  # j = 3k + 1 => label 1, 4, 7, ...
                new_state[i] = 1 - state[i]
        return tuple(new_state)

    # Button operations
    buttons = [button1, button2, button3, button4]

    # BFS to find all reachable states within 'presses' moves
    for _ in range(presses):
        next_level = []
        while queue:
            current_state = queue.popleft()

            # Try pressing each button
            for button in buttons:
                new_state = button(current_state)
                if new_state not in visited:
                    visited.add(new_state)
                    next_level.append(new_state)

        # Add next level to queue
        queue.extend(next_level)

    return len(visited)
