    def calculate(self, s: str) -> int:
        # Remove spaces
        s = s.replace(' ', '')

        # Stack to store numbers
        stack = []
        # Current number being built
        current_num = 0
        # Current operator
        current_op = '+'

        for i in range(len(s)):
            char = s[i]

            if char.isdigit():
                current_num = current_num * 10 + int(char)

            # If we hit an operator or end of string
            if (i == len(s) - 1) or (char in '+-*/'):
